random.seed(17)
def sig(adj,mask):
 vs=[i for i in range(len(adj)) if mask>>i&1];out=[];seen=0
 for i in vs:
  if (adj[i]&mask).bit_count()>2:return None
 for i in vs:
  if seen>>i&1:continue
  stack=[i];seen|=1<<i;nv=ne=0
  while stack:
   j=stack.pop();nv+=1;nb=adj[j]&mask;ne+=nb.bit_count()
