import networkx as nx,random
random.seed(321)
def properties(J):
 comps=[J.subgraph(c) for c in nx.connected_components(J) if len(c)>1]
 path4=all(nx.is_tree(C) and len(C)<=4 and max(dict(C.degree()).values())<=2 for C in comps)
 star3=all(nx.is_tree(C) and max(dict(C.degree()).values())==len(C)-1 and len(C)<=4 for C in comps)
 tri=all(len(C)<=3 for C in comps)
 cyc4=all((nx.is_tree(C) and max(dict(C.degree()).values())<=2 and len(C)<=4) or (len(C)==4 and all(d==2 for v,d in C.degree())) for C in comps)
 kind=None
 if len(comps)==1 and len(comps[0])==5 and nx.is_tree(comps[0]):
  ds=sorted(dict(comps[0].degree()).values())
  kind={ (1,1,1,1,4):'star',(1,1,2,2,2):'path',(1,1,1,2,3):'broom'}.get(tuple(ds))
 return path4,star3,tri,cyc4,kind
for nf in range(9,21):
 qualified=0
 for rep in range(10000):
  F=nx.random_labeled_tree(nf,seed=random.randrange(1000000000));A,B=nx.bipartite.sets(F)
